/*
 * Builds the design-system bundle that mirrors the SHIPPING app UI, for upload
 * to a claude.ai/design design-system project (see docs/DESIGN_MIRROR.md).
 *
 * Everything here is DERIVED, never re-drawn:
 *
 *  - Tokens come from `src/renderer/theme/themes.ts` — the app's own single
 *    source of truth — compiled and imported, so a new token or a changed hex
 *    reaches the design project by rebuilding rather than by someone noticing.
 *    The previous handoff files hard-coded their palette and had already drifted
 *    (Geist where the app ships Maplestory, and missing every token added since:
 *    warning-*, compact-zone, live-bd, shadow-strong…).
 *  - The stylesheets are COPIED byte-for-byte. They are plain CSS with no build
 *    step, so the design pages are styled by the same rules the app runs.
 *  - The fonts ship as the same woff2 files the app bundles. Without them the
 *    pages would silently fall back to a system stack and misreport the type.
 *
 * Screen/component markup is captured separately from the running app by
 * `scripts/capture-design-surfaces.mjs`, which writes into the same bundle.
 *
 * Run: node scripts/build-design-bundle.mjs [--out <dir>]
 */
import { build } from "esbuild";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outArgIndex = process.argv.indexOf("--out");
export const BUNDLE_DIR = outArgIndex > 0
  ? path.resolve(process.argv[outArgIndex + 1])
  : path.join(root, "build", "design-bundle");

const RENDERER = path.join(root, "src", "renderer");

/** Compiles `themes.ts` and imports it, so the tokens are the app's own values. */
async function loadThemes() {
  const result = await build({
    entryPoints: [path.join(RENDERER, "theme", "themes.ts")],
    bundle: true,
    write: false,
    format: "esm",
    platform: "neutral",
  });
  const code = result.outputFiles[0].text;
  const module = await import(`data:text/javascript;base64,${Buffer.from(code).toString("base64")}`);
  const themes = module.THEMES;
  if (!Array.isArray(themes) || themes.length === 0) {
    throw new Error("themes.ts exported no THEMES array — the token source moved.");
  }
  return themes;
}

/**
 * The same CSS the app's ThemeProvider injects at runtime.
 *
 * The design pages are static files with no provider, so without this every
 * `var(--token)` in styles.css would resolve to nothing and every page would
 * render unstyled — the first thing to check if a card looks blank.
 */
function tokensCss(themes) {
  const blockFor = (theme, selector) => {
    const lines = [
      `${selector} {`,
      `  color-scheme: ${theme.scheme};`,
      ...Object.entries(theme.color).map(([token, value]) => `  --${token}: ${value};`),
      ...Object.entries(theme.shape).map(([token, value]) => `  --${token}: ${value};`),
      "}",
    ];
    return lines.join("\n");
  };
  const [first, ...rest] = themes;
  return [
    "/* GENERATED by scripts/build-design-bundle.mjs from src/renderer/theme/themes.ts.",
    "   Do not edit here — edit the theme and rebuild, or the design project starts",
    "   disagreeing with the app, which is the drift this file exists to end. */",
    "",
    `/* Default theme: ${first.label} (first entry of THEMES, exactly as the app does). */`,
    blockFor(first, ":root"),
    "",
    ...themes.map((theme) => `${blockFor(theme, `:root[data-theme="${theme.id}"]`)}\n`),
  ].join("\n");
}

/** A one-line card marker; the Design System pane builds its index from these. */
export function dsCard(group, name, subtitle) {
  const attrs = [`group="${group}"`, `name="${name}"`];
  if (subtitle) attrs.push(`subtitle="${subtitle}"`);
  return `<!-- @dsCard ${attrs.join(" ")} -->`;
}

/**
 * Wraps captured markup in a page that loads the app's real stylesheets.
 *
 * `theme` sets `data-theme` exactly as the app's title-bar switcher does, so a
 * card can show the same surface in either theme without a second capture.
 */
export function page({ group, name, subtitle, theme = "light", body, bodyClass = "", depth = 1 }) {
  const up = "../".repeat(depth);
  return `${dsCard(group, name, subtitle)}
<!DOCTYPE html>
<html lang="ko" data-theme="${theme}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${name}</title>
<link rel="stylesheet" href="${up}foundations/tokens.css">
<link rel="stylesheet" href="${up}app/design-system.css">
<link rel="stylesheet" href="${up}app/styles.css">
<link rel="stylesheet" href="${up}foundations/stage.css">
</head>
<body class="ds-stage ${bodyClass}">
${body}
</body>
</html>
`;
}

/**
 * The only styling this bundle adds on top of the app's own.
 *
 * Kept to a MINIMUM and scoped to `.ds-stage`: a page that restyles the
 * component it is documenting stops being evidence of what the app looks like.
 * This paints the surrounding page and lays out specimen rows, nothing else.
 */
const STAGE_CSS = `/* Stage chrome for the design cards — never component styling. */
.ds-stage {
  margin: 0;
  padding: 24px;
  background: var(--bg-0);
  color: var(--text-0);
  font-family: var(--font-sans);
}
.ds-stage.is-flush { padding: 0; }
.ds-section { margin: 0 0 28px; }
.ds-section:last-child { margin-bottom: 0; }
.ds-label {
  margin: 0 0 10px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .6px;
  text-transform: uppercase;
  color: var(--text-3);
}
.ds-note { margin: 0 0 14px; font-size: 12px; color: var(--text-2); max-width: 62ch; }
.ds-row { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 14px; }
.ds-col { display: flex; flex-direction: column; gap: 14px; }
.ds-surface {
  background: var(--bg-1);
  border: var(--border-width) solid var(--border-subtle);
  border-radius: var(--radius-panel);
  padding: 14px;
}
.ds-swatches { display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: 10px; }
.ds-swatch {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  background: var(--bg-2);
  border: var(--border-width) solid var(--border-subtle);
  border-radius: var(--radius-card);
}
.ds-chip {
  width: 34px;
  height: 34px;
  flex: none;
  border-radius: var(--radius-button);
  border: var(--border-width) solid var(--border);
}
.ds-swatch-text { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ds-swatch-name { font-family: var(--font-mono); font-size: 11px; color: var(--text-0); }
.ds-swatch-value { font-family: var(--font-mono); font-size: 10px; color: var(--text-3); }
.ds-shape-row { display: flex; align-items: flex-end; gap: 14px; flex-wrap: wrap; }
.ds-shape {
  width: 78px;
  height: 54px;
  display: grid;
  place-items: end center;
  padding-bottom: 6px;
  background: var(--bg-2);
  border: var(--border-width) solid var(--border);
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--text-3);
}
.ds-type-row { display: flex; align-items: baseline; gap: 14px; padding: 7px 0; border-bottom: var(--border-width) solid var(--border-subtle); }
.ds-type-row:last-child { border-bottom: 0; }
.ds-type-meta { flex: none; width: 132px; font-family: var(--font-mono); font-size: 10.5px; color: var(--text-3); }
`;

function copyInto(fromPath, toPath) {
  fs.mkdirSync(path.dirname(toPath), { recursive: true });
  fs.copyFileSync(fromPath, toPath);
}

/** Foundations: the color, shape and type ramps, read from the same tokens. */
function foundationPages(themes) {
  const swatch = (token) => `<div class="ds-swatch"><span class="ds-chip" style="background: var(--${token})"></span><span class="ds-swatch-text"><span class="ds-swatch-name">--${token}</span><span class="ds-swatch-value">${themes[0].color[token] || themes[0].shape[token] || ""}</span></span></div>`;
  const colorTokens = Object.keys(themes[0].color);
  const shapeTokens = Object.keys(themes[0].shape);

  const colorBody = themes.map((theme) => `<section class="ds-section">
  <p class="ds-label">${theme.label} — ${theme.id}</p>
  <div class="ds-swatches" data-theme="${theme.id}" style="color-scheme:${theme.scheme}">
    ${colorTokens.map((token) => `<div class="ds-swatch"><span class="ds-chip" style="background: ${theme.color[token]}"></span><span class="ds-swatch-text"><span class="ds-swatch-name">--${token}</span><span class="ds-swatch-value">${theme.color[token]}</span></span></div>`).join("\n    ")}
  </div>
</section>`).join("\n");

  const shapeBody = `<section class="ds-section">
  <p class="ds-label">Radii &amp; borders</p>
  <p class="ds-note">Shape is themable in AgentParty: a theme can round or flatten the whole UI without touching a component, so these are tokens rather than literals.</p>
  <div class="ds-shape-row">
    ${shapeTokens.filter((token) => token.startsWith("radius")).map((token) => `<div class="ds-shape" style="border-radius: var(--${token})">--${token}</div>`).join("\n    ")}
  </div>
</section>
<section class="ds-section">
  <p class="ds-label">Widths</p>
  <div class="ds-row">
    ${shapeTokens.filter((token) => !token.startsWith("radius")).map((token) => `<div class="ds-shape" style="border-width: var(--${token})">--${token}: ${themes[0].shape[token]}</div>`).join("\n    ")}
  </div>
</section>`;

  const typeRamp = [
    ["Panel / member name", "font-size:12.5px;font-weight:600", "멤버 이름 · Member name"],
    ["Body — transcript", "font-size:13px", "모델이 쓴 본문 텍스트입니다. The transcript body."],
    ["Secondary", "font-size:12px;color:var(--text-2)", "부가 설명 · Secondary copy"],
    ["Caption", "font-size:11px;color:var(--text-3)", "캡션 · Caption"],
    ["Mono — tool output", "font-family:var(--font-mono);font-size:11.5px", "npm run build · exit 0"],
    ["Section label", "font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--text-3)", "Section label"],
  ];
  const typeBody = `<section class="ds-section">
  <p class="ds-label">Type</p>
  <p class="ds-note">UI text is <b>Maplestory</b> (bundled woff2, offline-safe); tool output and identifiers keep a monospace stack because Maplestory is not fixed-width.</p>
  <div class="ds-surface">
    ${typeRamp.map(([label, style, sample]) => `<div class="ds-type-row"><span class="ds-type-meta">${label}</span><span style="${style}">${sample}</span></div>`).join("\n    ")}
  </div>
</section>`;

  return [
    { path: "foundations/color.html", html: page({ group: "Foundations", name: "Color tokens", subtitle: `${colorTokens.length} tokens × ${themes.length} themes`, body: colorBody, depth: 1 }) },
    { path: "foundations/shape.html", html: page({ group: "Foundations", name: "Shape tokens", subtitle: "Radii, border and focus widths", body: shapeBody, depth: 1 }) },
    { path: "foundations/type.html", html: page({ group: "Foundations", name: "Type", subtitle: "Maplestory UI + mono stack", body: typeBody, depth: 1 }) },
  ];
}

async function main() {
  const themes = await loadThemes();
  fs.rmSync(BUNDLE_DIR, { recursive: true, force: true });
  fs.mkdirSync(BUNDLE_DIR, { recursive: true });

  const write = (relativePath, contents) => {
    const target = path.join(BUNDLE_DIR, relativePath);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, contents);
    return target;
  };

  write("foundations/tokens.css", tokensCss(themes));
  write("foundations/stage.css", STAGE_CSS);
  // Byte-for-byte copies: the design pages must be styled by the app's rules,
  // not by a transcription of them.
  copyInto(path.join(RENDERER, "styles.css"), path.join(BUNDLE_DIR, "app", "styles.css"));
  copyInto(path.join(RENDERER, "design-system.css"), path.join(BUNDLE_DIR, "app", "design-system.css"));
  for (const font of fs.readdirSync(path.join(RENDERER, "assets", "fonts"))) {
    // design-system.css asks for `./assets/fonts/<file>`, so the copy keeps that
    // exact shape relative to the stylesheet.
    copyInto(path.join(RENDERER, "assets", "fonts", font), path.join(BUNDLE_DIR, "app", "assets", "fonts", font));
  }
  for (const file of foundationPages(themes)) {
    write(file.path, file.html);
  }

  const manifest = {
    generatedFrom: "src/renderer/theme/themes.ts + src/renderer/styles.css (copied verbatim)",
    themes: themes.map((theme) => ({ id: theme.id, label: theme.label, scheme: theme.scheme })),
    colorTokens: Object.keys(themes[0].color).length,
    shapeTokens: Object.keys(themes[0].shape).length,
  };
  write("foundations/_source.json", `${JSON.stringify(manifest, null, 2)}\n`);

  console.log(`design bundle → ${BUNDLE_DIR}`);
  console.log(`  themes: ${manifest.themes.map((t) => t.id).join(", ")}`);
  console.log(`  tokens: ${manifest.colorTokens} color + ${manifest.shapeTokens} shape`);
  console.log("  next: node scripts/capture-design-surfaces.mjs   (adds the screens/components)");
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("build-design-bundle.mjs")) {
  main().catch((error) => { console.error(error); process.exit(1); });
}
